pragma solidity >=0.8.0;

contract EventProbe {
    event Single(uint256 indexed value);
    event Multi(address indexed who, uint256 indexed a, string indexed tag);
    event WithBytes(bytes indexed blob, uint256 plain);

    uint256 public counter;

    constructor() {
        emit Single(0);
        emit Multi(msg.sender, 0, "ctor");
    }

    function emitAll(string memory tag, bytes memory blob) public {
        counter += 1;
        emit Single(counter);
        emit Multi(msg.sender, counter, tag);
        emit WithBytes(blob, counter);
        emit Single(counter);
    }
}
